import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.Bqa2y7hU.js";const p=JSON.parse('{"title":"配置项","description":"Xiaoyi_QQ_V4 配置文件 config/bot.toml 的全部配置项：默认值、取值范围与说明。","frontmatter":{"title":"配置项","description":"Xiaoyi_QQ_V4 配置文件 config/bot.toml 的全部配置项：默认值、取值范围与说明。"},"headers":[],"relativePath":"reference/config.md","filePath":"reference/config.md","lastUpdated":1789268494000}'),c={name:"reference/config.md"};function r(i,t,s,l,n,h){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="配置项-📋" tabindex="-1">配置项 📋 <a class="header-anchor" href="#配置项-📋" aria-label="Permalink to &quot;配置项 📋&quot;">​</a></h1><p>这页是 <code>config/bot.toml</code> 的完整参考。文件按 <code>[段]</code> 组织，下面逐个段落列出键名、默认值与说明。<strong>改了配置文件必须重启服务才生效</strong>（面板里改的除外，见文末）。</p><p>文件位置：<code>.deb</code> 安装后在 <code>/opt/xiaoyi_qq_c/config/bot.toml</code>。</p><h2 id="app-应用信息" tabindex="-1">[app] 应用信息 <a class="header-anchor" href="#app-应用信息" aria-label="Permalink to &quot;[app] 应用信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键名</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>&quot;xbot&quot;</code></td><td>应用名称，用于日志与界面标识</td></tr><tr><td><code>env</code></td><td><code>&quot;development&quot;</code></td><td>运行环境。<strong>安装向导写入的是 <code>production</code></strong>；在 <code>production</code> 下找回密码等流程遵循生产安全策略，不再返回开发链接</td></tr></tbody></table><h2 id="server-监听地址" tabindex="-1">[server] 监听地址 <a class="header-anchor" href="#server-监听地址" aria-label="Permalink to &quot;[server] 监听地址&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键名</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>data_listen</code></td><td><code>&quot;0.0.0.0:8081&quot;</code></td><td>适配器数据面监听地址。QQ 平台侧的连接（如 OneBot 反向 WS）走这里</td></tr><tr><td><code>admin_listen</code></td><td><code>&quot;0.0.0.0:8080&quot;</code></td><td>控制台 / Web 界面监听地址</td></tr><tr><td><code>frontend_embed</code></td><td><code>false</code></td><td>是否使用内嵌前端资源。默认 <code>false</code>，前端已编译进二进制，通常无需改动</td></tr></tbody></table><h2 id="log-日志" tabindex="-1">[log] 日志 <a class="header-anchor" href="#log-日志" aria-label="Permalink to &quot;[log] 日志&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键名</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>level</code></td><td><code>&quot;info&quot;</code></td><td>日志级别，可选 <code>trace</code> / <code>debug</code> / <code>info</code> / <code>warn</code> / <code>error</code>。排障时临时调低</td></tr><tr><td><code>dir</code></td><td><code>&quot;logs&quot;</code></td><td>日志文件输出目录（相对程序目录）</td></tr><tr><td><code>json</code></td><td><code>false</code></td><td>是否输出结构化 JSON 日志，便于对接日志采集系统</td></tr></tbody></table><h2 id="threads-线程数" tabindex="-1">[threads] 线程数 <a class="header-anchor" href="#threads-线程数" aria-label="Permalink to &quot;[threads] 线程数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键名</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>io_data</code></td><td><code>0</code></td><td>数据面 IO 线程数。<code>0</code> 表示按 CPU 核数自动决定</td></tr><tr><td><code>worker</code></td><td><code>0</code></td><td>工作线程数。<code>0</code> 表示按 CPU 核数自动决定</td></tr><tr><td><code>admin</code></td><td><code>8</code></td><td>控制台 / 管理接口线程数。安装向导生成的配置会写 <code>2</code>；机器配置低时保持小值即可</td></tr></tbody></table><h2 id="database-数据库" tabindex="-1">[database] 数据库 <a class="header-anchor" href="#database-数据库" aria-label="Permalink to &quot;[database] 数据库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键名</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>host</code></td><td><code>&quot;localhost&quot;</code></td><td>PostgreSQL 地址。安装向导会写入你在向导里填的值（常见是 <code>127.0.0.1</code>）</td></tr><tr><td><code>port</code></td><td><code>5432</code></td><td>PostgreSQL 端口</td></tr><tr><td><code>user</code></td><td><code>&quot;&quot;</code></td><td>数据库用户名</td></tr><tr><td><code>password</code></td><td><code>&quot;&quot;</code></td><td>数据库密码</td></tr><tr><td><code>dbname</code></td><td><code>&quot;&quot;</code></td><td>数据库名</td></tr><tr><td><code>pool_size</code></td><td><code>10</code></td><td>连接池大小</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这些值由安装向导写入</p><p>首次配置时向导会把你在页面上填的内容写进这一段。手工改这里之后记得重启服务，并用 <code>/readyz</code> 确认数据库连得上。</p></div><h2 id="payment-支付" tabindex="-1">[payment] 支付 <a class="header-anchor" href="#payment-支付" aria-label="Permalink to &quot;[payment] 支付&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键名</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>false</code></td><td>是否启用在线支付</td></tr><tr><td><code>apiurl</code></td><td><code>&quot;&quot;</code></td><td>支付网关接口地址</td></tr><tr><td><code>pid</code></td><td><code>&quot;&quot;</code></td><td>支付网关商户号</td></tr><tr><td><code>key</code></td><td><code>&quot;&quot;</code></td><td>支付网关商户密钥</td></tr><tr><td><code>sign_type</code></td><td><code>&quot;&quot;</code></td><td>签名方式，默认为 <code>MD5</code></td></tr><tr><td><code>private_key</code></td><td><code>&quot;&quot;</code></td><td>商户私钥（网关要求非对称签名时使用）</td></tr><tr><td><code>public_key</code></td><td><code>&quot;&quot;</code></td><td>网关公钥，用于校验回调</td></tr><tr><td><code>sitename</code></td><td><code>&quot;&quot;</code></td><td>站点名称，展示在支付页</td></tr><tr><td><code>notify_url</code></td><td><code>&quot;&quot;</code></td><td>异步回调地址</td></tr><tr><td><code>return_url</code></td><td><code>&quot;&quot;</code></td><td>同步跳转地址</td></tr></tbody></table><h2 id="smtp-邮件" tabindex="-1">[smtp] 邮件 <a class="header-anchor" href="#smtp-邮件" aria-label="Permalink to &quot;[smtp] 邮件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键名</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>false</code></td><td>是否启用邮件发送（注册验证码、找回密码等）</td></tr><tr><td><code>host</code></td><td><code>&quot;&quot;</code></td><td>SMTP 服务器地址</td></tr><tr><td><code>port</code></td><td><code>465</code></td><td>SMTP 端口</td></tr><tr><td><code>user</code></td><td><code>&quot;&quot;</code></td><td>SMTP 用户名</td></tr><tr><td><code>password</code></td><td><code>&quot;&quot;</code></td><td>SMTP 密码 / 授权码</td></tr><tr><td><code>from</code></td><td><code>&quot;&quot;</code></td><td>发件人地址</td></tr><tr><td><code>from_name</code></td><td><code>&quot;&quot;</code></td><td>发件人显示名称</td></tr><tr><td><code>ssl</code></td><td><code>true</code></td><td>是否使用 SSL 直连（对应 465 端口）</td></tr><tr><td><code>starttls</code></td><td><code>false</code></td><td>是否使用 STARTTLS 升级（通常与 <code>ssl</code> 二选一）</td></tr></tbody></table><h2 id="retention-数据保留" tabindex="-1">[retention] 数据保留 <a class="header-anchor" href="#retention-数据保留" aria-label="Permalink to &quot;[retention] 数据保留&quot;">​</a></h2><p>控制自动清理策略，程序<strong>每 6 小时</strong>执行一次清理。天数设为 <code>0</code> 表示永久保留、不清理。</p><table tabindex="0"><thead><tr><th>键名</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>event_days</code></td><td><code>7</code></td><td>消息留痕保留天数</td></tr><tr><td><code>notify_days</code></td><td><code>30</code></td><td>通知保留天数</td></tr><tr><td><code>audit_days</code></td><td><code>90</code></td><td>审计日志保留天数</td></tr><tr><td><code>user_log_days</code></td><td><code>90</code></td><td>用户日志保留天数</td></tr><tr><td><code>ai_conv_days</code></td><td><code>30</code></td><td>AI 会话保留天数</td></tr><tr><td><code>kv_days</code></td><td><code>0</code></td><td>插件 KV 保留天数，<code>0</code> 表示永久</td></tr><tr><td><code>interval_hours</code></td><td><code>6</code></td><td>自动清理的执行间隔（小时）</td></tr></tbody></table><h2 id="plugin-内置插件装载-一般不用改" tabindex="-1">[[plugin]] 内置插件装载（一般不用改） <a class="header-anchor" href="#plugin-内置插件装载-一般不用改" aria-label="Permalink to &quot;[[plugin]] 内置插件装载（一般不用改）&quot;">​</a></h2><p>配置文件里还可以有多个 <code>[[plugin]]</code> 段，用来声明<strong>随程序分发的内置插件</strong>：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code     = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;echo&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 插件标识</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">so       = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;plugins/libecho.so&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled  = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">priority = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span></span></code></pre></div><ul><li>这一段只影响<strong>内置插件</strong>的装载；从控制台上传的插件、以及「插件装到哪台机器人」的绑定关系，<strong>都存在数据库里</strong>，由控制台管理。</li><li>数据库里没有任何插件记录时，程序才会回退用这里的配置。正常通过控制台装插件的用户<strong>不需要改这段</strong>。</li></ul><h2 id="哪些配置在面板里也能改" tabindex="-1">哪些配置在面板里也能改 <a class="header-anchor" href="#哪些配置在面板里也能改" aria-label="Permalink to &quot;哪些配置在面板里也能改&quot;">​</a></h2><p>下面这些不用改文件，在控制台「平台设置」里就能改，<strong>且面板里的值会覆盖配置文件</strong>：</p><ul><li>支付相关配置</li><li>SMTP 邮件配置</li><li>站点域名</li><li>注册策略</li><li>AI 助手</li></ul><p>所以排查「我明明改了配置文件怎么没生效」时，先去「平台设置」看一眼是不是面板里有值把它盖掉了。</p><h2 id="改完要重启吗" tabindex="-1">改完要重启吗 <a class="header-anchor" href="#改完要重启吗" aria-label="Permalink to &quot;改完要重启吗&quot;">​</a></h2><table tabindex="0"><thead><tr><th>改法</th><th>是否要重启</th></tr></thead><tbody><tr><td>直接编辑 <code>config/bot.toml</code></td><td><strong>需要</strong>重启服务：<code>sudo systemctl restart xiaoyi-qq-c</code></td></tr><tr><td>在控制台「平台设置」里改</td><td><strong>立即生效</strong>，不需要重启</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/deploy/config">首次配置</a></li><li><a href="/RuaBot.Doc/deploy/ops">备份与运维</a></li><li><a href="/RuaBot.Doc/guide/requirements">系统要求</a></li></ul>`,33)])])}const b=d(c,[["render",r]]);export{p as __pageData,b as default};
